CREATE TABLE stock_moves(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),code text NOT NULL UNIQUE DEFAULT('MOVE-'||gen_random_uuid()::text),project_id uuid NOT NULL REFERENCES projects(id),customer_id uuid NOT NULL REFERENCES customers(id),target_location_id uuid NOT NULL REFERENCES locations(id),status text NOT NULL DEFAULT 'DRAFT' CHECK(status IN('DRAFT','CONFIRMED')),reason text NOT NULL CHECK(length(trim(reason)) BETWEEN 1 AND 500),created_by uuid NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),confirmed_at timestamptz,version int NOT NULL DEFAULT 1,FOREIGN KEY(project_id,customer_id) REFERENCES customers(project_id,id));
CREATE TABLE stock_move_items(move_id uuid NOT NULL REFERENCES stock_moves(id),bundle_id uuid NOT NULL REFERENCES bundles(id),from_location_id uuid NOT NULL REFERENCES locations(id),expected_version int NOT NULL,PRIMARY KEY(move_id,bundle_id));
CREATE TRIGGER move_history BEFORE UPDATE OR DELETE ON stock_moves FOR EACH ROW EXECUTE FUNCTION v23_state_owner();
CREATE TRIGGER move_items_history BEFORE UPDATE OR DELETE ON stock_move_items FOR EACH ROW EXECUTE FUNCTION v23_immutable();
CREATE FUNCTION confirm_stock_move(actor uuid,doc uuid) RETURNS stock_moves LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE d stock_moves;target locations;i stock_move_items;b bundles;w uuid;BEGIN
 SELECT * INTO d FROM stock_moves WHERE id=doc FOR UPDATE;IF NOT FOUND OR d.status<>'DRAFT' THEN RAISE EXCEPTION 'Move already confirmed' USING ERRCODE='23514';END IF;
 SELECT x.* INTO target FROM locations x JOIN warehouses h ON h.id=x.warehouse_id WHERE x.id=d.target_location_id AND x.project_id=d.project_id AND x.active AND h.active AND NOT EXISTS(SELECT 1 FROM yards y WHERE y.id=x.yard_id AND NOT y.active) FOR SHARE OF x,h;
 IF NOT FOUND THEN RAISE EXCEPTION 'Move destination inactive or mismatched' USING ERRCODE='23514';END IF;
 PERFORM v23_require(actor,'move:write',d.project_id,d.customer_id,target.warehouse_id);
 IF NOT EXISTS(SELECT 1 FROM stock_move_items WHERE move_id=doc) THEN RAISE EXCEPTION 'Move empty' USING ERRCODE='23514';END IF;
 FOR i IN SELECT * FROM stock_move_items WHERE move_id=doc ORDER BY bundle_id LOOP
 SELECT * INTO b FROM bundles WHERE id=i.bundle_id FOR UPDATE;SELECT warehouse_id INTO w FROM locations WHERE id=b.location_id;PERFORM v23_require(actor,'move:write',d.project_id,d.customer_id,w);
 IF b.project_id<>d.project_id OR b.physical_status<>'IN_STOCK' OR b.version<>i.expected_version OR b.location_id<>i.from_location_id OR b.location_id=target.id OR EXISTS(SELECT 1 FROM loading_items WHERE bundle_id=b.id AND active) THEN RAISE EXCEPTION 'Move bundle changed, loaded or already at destination' USING ERRCODE='23514';END IF;
 UPDATE bundles SET location_id=target.id,version=version+1 WHERE id=b.id;
 INSERT INTO inventory_events(bundle_id,event_type,physical_delta,actor_id,before_data,after_data) VALUES(b.id,'MOVE',0,actor,jsonb_build_object('location_id',i.from_location_id),jsonb_build_object('move_id',doc,'code',d.code,'location_id',target.id,'location',target.code,'reason',d.reason));END LOOP;
 UPDATE stock_moves SET status='CONFIRMED',confirmed_at=now(),version=version+1 WHERE id=doc RETURNING * INTO d;
 INSERT INTO audit_logs(actor_id,action,entity_type,entity_id,after_data) VALUES(actor,'stock_move_confirmed','stock_moves',doc::text,to_jsonb(d));RETURN d;END $$;
REVOKE ALL ON FUNCTION confirm_stock_move(uuid,uuid) FROM PUBLIC;GRANT EXECUTE ON FUNCTION confirm_stock_move(uuid,uuid) TO musonoi_app;
GRANT SELECT,INSERT ON stock_moves,stock_move_items TO musonoi_app;
CREATE OR REPLACE VIEW inventory_view AS SELECT b.id AS uuid,b.bundle_no AS id,b.project_id,b.customer_id,l.warehouse_id,c.name AS customer,l.code AS location,t.code AS batch,b.net_weight AS weight,CASE WHEN b.physical_status='OUTBOUND' THEN '已出库' WHEN r.id IS NOT NULL THEN '已预留' ELSE '在库' END AS status,CASE b.sample_status WHEN 'NOT_SAMPLED' THEN '未取样' WHEN 'SAMPLING' THEN '取样中' ELSE '已取样' END AS sample,to_char(b.inbound_date,'YYYY-MM-DD') AS date,b.grade,b.purity,b.data_kind,b.version,p.customer_id AS allocated_customer_id,ac.name AS allocated_customer,a.code AS allocation_code,p.code AS sales_plan_code,doc.code AS receipt_code,doc.confirmed_at,to_char(b.production_date,'YYYY-MM-DD') AS production_date,b.inbound_at,u.display_name AS inbound_operator,b.remark,b.receipt_id,dispatch.customer_id AS dispatched_customer_id,dispatch.code AS outbound_code,dispatch.vehicle_no,dispatch.departed_at,dispatch.customer_name AS dispatched_customer FROM bundles b JOIN customers c ON c.id=b.customer_id JOIN locations l ON l.id=b.location_id JOIN batches t ON t.id=b.batch_id LEFT JOIN reservations r ON r.bundle_id=b.id AND r.released_at IS NULL LEFT JOIN allocations a ON a.id=r.allocation_id LEFT JOIN sales_plans p ON p.id=a.plan_id LEFT JOIN customers ac ON ac.id=p.customer_id LEFT JOIN receipts doc ON doc.id=b.receipt_id LEFT JOIN users u ON u.id=doc.created_by LEFT JOIN LATERAL(SELECT d.customer_id,d.code,d.departed_at,o.vehicle_no,c.name AS customer_name FROM outbound_orders d JOIN loading_orders o ON o.id=d.loading_id JOIN loading_items z ON z.loading_id=o.id JOIN customers c ON c.id=d.customer_id WHERE z.bundle_id=b.id AND d.status='DEPARTED' AND b.physical_status='OUTBOUND' ORDER BY d.departed_at DESC LIMIT 1) dispatch ON true;
